def low_stock(rows, threshold):
    for row in rows:
        if row["stock"] < threshold:
            yield row["sku"]

rows = [{"sku": "a", "stock": 1}, {"sku": "b", "stock": 8}]
alerts = low_stock(rows, 3)
print(list(alerts))
