from tempfile import TemporaryDirectory
from pathlib import Path
import json
from report import build_report

with TemporaryDirectory() as folder:
    source = Path(folder) / "catalog.csv"
    target = Path(folder) / "report.json"
    source.write_text("sku,stock\na,3\nb,0\n", encoding="utf-8")
    assert build_report(source, target) == {"products": 2, "units": 3}
    assert not target.exists()
    build_report(source, target, dry_run=False)
    assert json.loads(target.read_text()) == {"products": 2, "units": 3}
    source.write_text("sku,stock\na,3\na,1\n", encoding="utf-8")
    try:
        build_report(source, target, dry_run=False)
    except ValueError:
        pass
    else:
        raise AssertionError("duplicate accepted")
    assert json.loads(target.read_text()) == {"products": 2, "units": 3}
